#!/usr/bin/env node
// Builds the two generated files the card and event editor needs (both gitignored):
//   out/html/editor/compiler.js  the dendrynexus compiler, bundled for the browser (global DryCompiler)
//   out/html/editor/sources.js   every source/scenes/**/*.scene.dry file (window.TA_SOURCES = {path: text})
// Run it after `npm run dendrynexus make-html` (or use `npm run build`, which runs both).
'use strict';

var fs = require('fs');
var path = require('path');

var repo = path.resolve(__dirname, '..');
var outDir = path.join(repo, 'out', 'html', 'editor');
fs.mkdirSync(outDir, {recursive: true});

// ---------------------------------------------------------------- sources
function walk(dir, list) {
  fs.readdirSync(dir).sort().forEach(function (f) {
    var p = path.join(dir, f);
    if (fs.statSync(p).isDirectory()) walk(p, list);
    else if (/\.dry$/.test(f)) list.push(p);
  });
  return list;
}

var sources = {};
walk(path.join(repo, 'source'), []).forEach(function (p) {
  var rel = path.relative(repo, p).split(path.sep).join('/');
  sources[rel] = fs.readFileSync(p, 'utf8');
});
fs.writeFileSync(path.join(outDir, 'sources.js'),
  '// Generated by tools/build_editor.js - do not edit.\nwindow.TA_SOURCES = ' + JSON.stringify(sources) + ';\n');
console.log('sources.js: ' + Object.keys(sources).length + ' files');

// ---------------------------------------------------------------- compiler
var browserify = require(path.join(repo, 'node_modules', 'browserify'));
var terser = require(path.join(repo, 'node_modules', 'terser'));
var entry = path.join(repo, 'node_modules', 'dendrynexus', 'lib', 'parsers', 'compiler.js');

browserify(entry, {standalone: 'DryCompiler'}).bundle(function (err, buf) {
  if (err) { console.error(err); process.exit(1); }
  terser.minify(buf.toString(), {compress: true, mangle: true}).then(function (res) {
    fs.writeFileSync(path.join(outDir, 'compiler.js'), '// Generated by tools/build_editor.js from dendrynexus (MIT) - do not edit.\n' + res.code + '\n');
    console.log('compiler.js: ' + Math.round(res.code.length / 1024) + ' KB');
  }).catch(function (e) { console.error(e); process.exit(1); });
});
